%[text] ## Initial 
close
%loadMapdt(2,1)
xyxyr = [50 300 1000 200 100];
vFcs = [-700 -500 -200 100 400 600 650];
iph = 1;% 1 or 2
%%
%[text] ## Panneling
msb = 2;nsb=5;
s.Avg = subplot(2,5,[2,3,4]); %[output:38bec072]
s.con(1) = subplot(2,5,1); %[output:38bec072]
s.con(2) = subplot(2,5,6); %[output:38bec072]
s.con(3) = subplot(2,5,7); %[output:38bec072]
s.con(4) = subplot(2,5,8); %[output:38bec072]
s.con(5) = subplot(2,5,9); %[output:38bec072]
s.con(6) = subplot(2,5,10); %[output:38bec072]
s.con(7) = subplot(2,5,5); %[output:38bec072]
f=gcf;
%%
%[text] 
V = map.vm*1000;
xrng = (0:xyxyr(5)) +xyxyr(-1 + iph*2);
yrng = (0:xyxyr(5)) +xyxyr(iph*2);
Gfcs = map.Gfinal0T(xrng,yrng,:);
f.CurrentAxes = s.Avg;
gfcs = squeeze(mean(mean(Gfcs)));
plot(V,gfcs) %[output:52b0d9ae]
xlim([-800 800]); %[output:52b0d9ae]
ylim([0 0.1]) %[output:52b0d9ae]
s.Avg.Clipping ="off"; %[output:52b0d9ae]
%%

% draw_triax([1 2 4]*500,[1 3 2]*.01)
%%
xline(vFcs) %[output:50c08e25]
s.Avg.Clipping %[output:51d591ca]
%%
isBottoms = [true false false false false false true];
for iE = 1:7 %[output:group:2f10d018]
    f.CurrentAxes = s.con(iE);
    [vv vi] = min(abs(V-vFcs(iE)));
    views(Gfcs(:,:,vi)) %[output:11faa2b6]
    colormap jet
    xticks([]);yticks([])
    center_preserve_resizeAx(s.con(iE),[1.2 1.2])
    resizeAxesToSquare(s.con(iE));
    draw_tri(s.Avg,s.con(iE),[vFcs(iE) 0],isBottoms(iE)) %[output:9911b92b] %[output:88dd8534] %[output:9dbe082b] %[output:8752d434] %[output:9f175833] %[output:95e63fa1] %[output:66347689] %[output:28b2faa1] %[output:8f28a779] %[output:5522dda9] %[output:24ae9daf] %[output:6ae1a80d] %[output:35cab195] %[output:0183b540] %[output:09ff0edf] %[output:3d8029e6] %[output:59b5e76b] %[output:4bd8919e] %[output:16c1a780] %[output:26bfe9d7] %[output:9eea36d8] %[output:653204e1] %[output:811ab2d5] %[output:399c0f90] %[output:0199af07] %[output:1651c82e] %[output:8761d96b] %[output:7eb31145] %[output:11faa2b6]
end %[output:group:2f10d018]





% Triangle Test

% Create Transformation Matrix
% xl = s.Avg.XLim
% yl = s.Avg.YLim
% xywh = s.Avg.Position
% 
% p1p2p3_A = [xl([1 1 2]);yl([1 2 2]);1 1 1] %p1:Top left p2: Bottom left p3: Bottom right
% p1p2p3_F = [((xywh([1 2]))'*[1 1 1] +[xywh(3) 0 0;0 0 xywh(4)]); 1 1 1]% p1p2p3_F = %It is normalized figure frame
% I_A__F = p1p2p3_A*inv(p1p2p3_F)

function sqaxResz(ax,r)
ax.Position = sqResz(ax.Position,r)
end

function xywh_new = sqResz(xywh_old,r)
wh_old = xywh_old([3,4]);
wh_new = wh_old*r;
xy_new = xywh_old([1,2])- (1/2)*(r-1)*wh_old;
xywh_new = [xy_new wh_new];
end

function center_preserve_resizeAx(ax,rr)
xywh_old = ax.Position;
xywh_new = center_preserve_resize(xywh_old,rr);
ax.Position = xywh_new;
% ax.Position = center_preserve_resize(ax.Position,rr)
end

function xywh_new = center_preserve_resize(xywh_old,rr)
wh_old = xywh_old([3,4]);
wh_new = wh_old.*rr;
xy_new = xywh_old([1,2])- (1/2)*(rr-1).*wh_old;
xywh_new = [xy_new wh_new];
end

function draw_tri(ax1,ax2,p1,isBottom)
%define 3 points
p1_ax1 = p1
xywh = ax2.Position
pAx2BL_ax2f = xywh([1 2]);
pAx2BR_ax2f = xywh([1 2]) + [xywh(3) 0];
if ~isBottom
    pAx2BL_ax2f = pAx2BL_ax2f + [0 xywh(4)];
    pAx2BR_ax2f = pAx2BR_ax2f + [0 xywh(4)];
end
pAx2BL_ax1 = figToAxesCoord(ax1, pAx2BL_ax2f);
pAx2BR_ax1 = figToAxesCoord(ax1, pAx2BR_ax2f);
tri_ax1 = [p1_ax1' pAx2BL_ax1' pAx2BR_ax1']

%drawtri_ax
f = gcf()
f.CurrentAxes = ax1;
draw_triax(tri_ax1(1,:),tri_ax1(2,:))
end

function draw_triax(vertices_x,vertices_y)
hold on
patch(vertices_x, vertices_y, 'k', 'FaceAlpha', 0.3,   'Clipping', 'off')
hold off
end

function resizeAxesToSquare(ax)
    % Validate input
    if nargin < 1 || ~isgraphics(ax, 'axes')
        error('Input must be a valid axes handle.');
    end

    % Get current axes position
    originalUnits = ax.Units;
    ax.Units = 'pixels';
    axPosition = ax.Position;

    % Determine the minimum dimension
    minDimension = min(axPosition(3:4));

    % Calculate new position to maintain center alignment
    newX = axPosition(1) + (axPosition(3) - minDimension) / 2;
    newY = axPosition(2) + (axPosition(4) - minDimension) / 2;

    % Set new position
    ax.Position = [newX, newY, minDimension, minDimension];

    % Restore original units
    ax.Units = originalUnits;
end


